def preparar(apps, schema_editor):
    """El permiso nuevo para los roles base y, en sistemas que ya estaban en uso, la función Control de ingreso apagada."""
    from core.permisos import PERMISOS, ROLES_BASE

    PermisosRol = apps.get_model("core", "PermisosRol")
    for pr in PermisosRol.objects.select_related("grupo").filter(grupo__name__in=ROLES_BASE):
        actuales = set(pr.permisos or [])
        nuevos = {c for c, _, _, roles in PERMISOS if c == "cobranzas.ingreso" and pr.grupo.name in roles}
        if not nuevos <= actuales:
            pr.permisos = sorted(actuales | nuevos)
            pr.save(update_fields=["permisos"])
    Ajustes = apps.get_model("core", "Ajustes")
    for a in Ajustes.objects.all():
        if "ingreso" not in (a.funciones_inactivas or []):
            a.funciones_inactivas = list(a.funciones_inactivas or []) + ["ingreso"]
            a.save(update_fields=["funciones_inactivas"])


